import { execFileSync } from "node:child_process";
import {
  chmodSync,
  cpSync,
  existsSync,
  mkdirSync,
  readdirSync,
  rmSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const desktopRoot = resolve(__dirname, "..");
const botRoot = resolve(desktopRoot, "..");
const bundleRoot = resolve(desktopRoot, ".bundle", "lingshi_bot");
const runtimeRoot = resolve(desktopRoot, "runtime");
const bundledNode = resolve(runtimeRoot, process.platform === "win32" ? "node.exe" : "node");
const requiredBundlePaths = [
  { src: resolve(botRoot, "openclaw.mjs"), dst: resolve(bundleRoot, "openclaw.mjs") },
  { src: resolve(botRoot, "dist"), dst: resolve(bundleRoot, "dist") },
];
const requiredDistEntry = resolve(botRoot, "dist", "entry.js");
const requiredControlUiIndex = resolve(botRoot, "dist", "control-ui", "index.html");

function ensureCleanDir(dir) {
  rmSync(dir, { recursive: true, force: true });
  mkdirSync(dir, { recursive: true });
}

function runPnpm(pnpmArgs) {
  const npmExecPath = process.env.npm_execpath;
  if (npmExecPath && existsSync(npmExecPath)) {
    execFileSync(process.execPath, [npmExecPath, ...pnpmArgs], {
      cwd: botRoot,
      stdio: "inherit",
    });
    return;
  }

  const pnpmBin = process.platform === "win32" ? "pnpm.cmd" : "pnpm";
  execFileSync(pnpmBin, pnpmArgs, {
    cwd: botRoot,
    stdio: "inherit",
  });
}

function ensureRuntimeArtifacts() {
  if (!existsSync(requiredDistEntry)) {
    console.log("dist/entry.js missing, building openclaw runtime artifacts...");
    runPnpm(["run", "build"]);
  }

  if (!existsSync(requiredDistEntry)) {
    throw new Error(`runtime_build_missing_entry: ${requiredDistEntry}`);
  }
}

function ensureControlUiArtifacts() {
  if (!existsSync(requiredControlUiIndex)) {
    console.log("dist/control-ui/index.html missing, building control UI assets...");
    runPnpm(["run", "ui:build"]);
  }

  if (!existsSync(requiredControlUiIndex)) {
    throw new Error(`control_ui_build_missing_index: ${requiredControlUiIndex}`);
  }
}

function runPnpmDeploy() {
  runPnpm([
    "--config.inject-workspace-packages=true",
    "--config.node-linker=hoisted",
    "--filter",
    "openclaw",
    "--prod",
    "deploy",
    bundleRoot,
  ]);
}

function resolveNodeExecutable() {
  const nodeFromEnv = process.env.LINGSHI_NODE_BIN || process.env.WEHELPER_NODE_BIN;
  if (nodeFromEnv && existsSync(nodeFromEnv)) {
    return nodeFromEnv;
  }
  return process.execPath;
}

function copyNodeRuntime() {
  mkdirSync(runtimeRoot, { recursive: true });
  const nodeBin = resolveNodeExecutable();
  cpSync(nodeBin, bundledNode);

  if (process.platform !== "win32") {
    const mode = statSync(nodeBin).mode;
    // Preserve executable bits from the host node runtime.
    chmodSync(bundledNode, mode);
  }
}

function writeBundleMeta() {
  const metaPath = join(desktopRoot, ".bundle", "README.txt");
  mkdirSync(dirname(metaPath), { recursive: true });
  writeFileSync(
    metaPath,
    [
      "Generated by lingshi_desktop/scripts/prepare-bundle.mjs",
      `Timestamp: ${new Date().toISOString()}`,
      `Node: ${process.execPath}`,
      "",
      "This directory is build-time output and should not be committed.",
    ].join("\n"),
    "utf8",
  );
}

function copyRequiredRuntimeFiles() {
  for (const { src, dst } of requiredBundlePaths) {
    if (!existsSync(src)) {
      throw new Error(`required_runtime_path_missing: ${src}`);
    }
    cpSync(src, dst, { recursive: true, force: true });
  }
}

function pruneBundleForDesktop() {
  const leanEnabled = process.env.LINGSHI_DESKTOP_LEAN !== "0";
  if (!leanEnabled) {
    return;
  }

  const removableRootPaths = [
    resolve(bundleRoot, "docs"),
    resolve(bundleRoot, "CHANGELOG.md"),
    resolve(bundleRoot, "README.md"),
    resolve(bundleRoot, "README-header.png"),
  ];

  for (const target of removableRootPaths) {
    rmSync(target, { recursive: true, force: true });
  }

  const nodeModulesRoot = resolve(bundleRoot, "node_modules");
  if (!existsSync(nodeModulesRoot)) {
    return;
  }

  // IMPORTANT: do not remove directories from node_modules.
  // Some packages (e.g. yaml) keep runtime JS under `doc/`.
  const removableFileExt = new Set([".map", ".markdown", ".mkd", ".rst", ".md", ".mdx", ".txt"]);

  function walk(dirPath) {
    const entries = readdirSync(dirPath, { withFileTypes: true });
    for (const entry of entries) {
      const entryPath = join(dirPath, entry.name);
      if (entry.isDirectory()) {
        walk(entryPath);
        continue;
      }
      if (!entry.isFile()) {
        continue;
      }
      const lower = entry.name.toLowerCase();
      const lastDot = lower.lastIndexOf(".");
      const ext = lastDot > -1 ? lower.slice(lastDot) : "";
      const shouldRemove = removableFileExt.has(ext);
      if (shouldRemove) {
        rmSync(entryPath, { force: true });
      }
    }
  }

  walk(nodeModulesRoot);
}

function main() {
  ensureRuntimeArtifacts();
  ensureControlUiArtifacts();
  ensureCleanDir(bundleRoot);
  runPnpmDeploy();
  copyRequiredRuntimeFiles();
  pruneBundleForDesktop();
  copyNodeRuntime();
  writeBundleMeta();
  console.log(`Bundled runtime ready at ${bundleRoot}`);
}

try {
  main();
} catch (error) {
  console.error("prepare-bundle failed:", error);
  process.exitCode = 1;
}
